import kotlinx.coroutines.*
import kotlinx.coroutines.channels.BufferOverflow
import kotlinx.coroutines.flow.*

// 模拟一个"快生产者"：每 50ms 发射一个自增读数（如传感器/行情推送）
fun sensor(): Flow<Int> = flow {
    var v = 0
    while (true) {
        emit(v++)
        delay(50)
    }
}

fun main() = runBlocking {
    val start = System.currentTimeMillis()

    val job = launch {
        sensor()
            // 上游算子：与生产者同协程执行，零额外开销（算子融合）
            .map { it * it }
            // 插入 Channel 边界：容量 2，满了丢最旧，永不挂起上游
            .buffer(capacity = 2, onBufferOverflow = BufferOverflow.DROP_OLDEST)
            // 下游是"慢消费者"：每个元素要花 200ms（如写库/渲染）
            .collect { v ->
                delay(200)
                println("[+${System.currentTimeMillis() - start}ms] collected=$v")
            }
    }

    delay(1100)
    job.cancel()              // 结构化并发：取消即停止整条流水线（上游 while(true) 也随之退出）
    job.join()
    println("pipeline cancelled, total=${System.currentTimeMillis() - start}ms")
}

